    if (page === 'nowplaying') return card(['show_cover_source_badge','nowplaying_song_title_marquee_enabled','nowplaying_immersive_mode','nowplaying_cover_lyrics_enabled','nowplaying_progress_show_quality_switch','nowplaying_progress_show_audio_codec','nowplaying_progress_show_audio_spec'], L('播放页信息','Now Playing Info'), '', env) + card(['nowplaying_keep_screen_on','nowplaying_toolbar_dock_enabled','nowplaying_control_placement','nowplaying_control_size','lyrics_control_size'], L('播放页控制','Now Playing Controls'), '', env);
