    if (page === 'storage') return storage(env);
    if (page === 'floating') return floating(env);
    if (page === 'cache-details') return '<section class="ap-card as-storage-summary"><div class="as-storage-total"><span class="as-storage-ring">' + env.icon('folder') + '</span><span><small>' + L('总占用','Total storage') + '</small><b>0 B</b><small>' + L('0 个文件','0 files') + '</small></span></div><div class="as-storage-cleanable"><span><small>' + L('可清理空间','Cleanable space') + '</small><b>0 B</b></span><span>' + env.button('data-as-action="cache-refresh" aria-label="' + L('刷新','Refresh') + '"', env.icon('history'), 'ap-icon-button') + env.button('data-as-action="cache-clear" aria-label="' + L('清理','Clear') + '"', env.icon('close'), 'ap-icon-button') + '</span></div>' + env.button('data-as-action="storage-system"', L('打开系统设置','Open system settings'), 'ap-text-button') + '</section><section class="ap-card"><p class="as-empty-note">' + L('暂未发现可计量文件','No measurable files found') + '</p></section>';
    if (page === 'together') return '<section class="ap-card">' + action('together-join', L('加入房间','Join room'), L('粘贴或输入邀请信息后加入房间','Paste or enter an invite to join a room'), env, 'person') + row(byKey.together_server, env) + row(byKey.together_nickname, env) + action('together-identity', L('重置唯一身份标识符','Reset unique identity'), L('重置后生成新的唯一身份标识符','Generate a new unique identity'), env, 'history') + '</section>';
